document.addEventListener("DOMContentLoaded",async()=>{let e=[];try{const t=await fetch("data/renewableCapacity.json");if(!t.ok)throw new Error("Network response was not ok");e=await t.json()}catch(t){console.error("Failed to fetch renewable capacity data:",t),e=[{year:2019,solarGW:34.6,windGW:37.5},{year:2020,solarGW:39.1,windGW:38.6},{year:2021,solarGW:49.3,windGW:40.1},{year:2022,solarGW:63.3,windGW:41.9},{year:2023,solarGW:73.3,windGW:44.7}]}document.getElementById("data-date").textContent="December 2023";const t=document.getElementById("renewableChart").getContext("2d"),a=!document.body.classList.contains("light-theme"),o=a?"#f0f0f0":"#333",n=a?"rgba(255, 255, 255, 0.1)":"rgba(0, 0, 0, 0.1)",r=e.map(e=>e.year),i=e.map(e=>e.solarGW),s=e.map(e=>e.windGW);new Chart(t,{type:"line",data:{labels:r,datasets:[{label:"Solar Capacity (GW)",data:i,borderColor:"#FDB813",backgroundColor:"rgba(253, 184, 19, 0.5)",fill:!0,tension:.4},{label:"Wind Capacity (GW)",data:s,borderColor:"#4CAF50",backgroundColor:"rgba(76, 175, 80, 0.5)",fill:!0,tension:.4}]},options:{responsive:!0,maintainAspectRatio:!1,plugins:{tooltip:{mode:"index",intersect:!1,callbacks:{label:function(e){return e.dataset.label+": "+e.parsed.y+" GW"}}},legend:{labels:{color:o}}},interaction:{mode:"nearest",axis:"x",intersect:!1},scales:{x:{stacked:!0,title:{display:!0,text:"Year",color:o},ticks:{color:o},grid:{color:n}},y:{stacked:!0,title:{display:!0,text:"Capacity (GW)",color:o},ticks:{color:o},grid:{color:n}}},animation:{duration:2e3,easing:"easeOutQuart"}}});const d=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting?"solar-growth"===e.target.id?document.getElementById("animated-sun").classList.add("sun-active"):"wind-growth"===e.target.id&&document.getElementById("animated-turbine").classList.add("turbine-active"):"solar-growth"===e.target.id?document.getElementById("animated-sun").classList.remove("sun-active"):"wind-growth"===e.target.id&&document.getElementById("animated-turbine").classList.remove("turbine-active")})},{root:null,rootMargin:"0px",threshold:.5});d.observe(document.getElementById("solar-growth")),d.observe(document.getElementById("wind-growth"))});